CREATE TABLE "orders" ("id" text PRIMARY KEY NOT NULL, "number" integer NOT NULL, "public_access_token" text NOT NULL, "customer_id" text REFERENCES "customers"("id"), "customer_name" text NOT NULL, "phone" text NOT NULL, "address" text NOT NULL, "address_number" text NOT NULL, "complement" text, "neighborhood" text NOT NULL, "notes" text, "payment_method" text NOT NULL, "subtotal_cents" integer NOT NULL, "total_cents" integer NOT NULL, "status" text DEFAULT 'pending' NOT NULL, "idempotency_key" text NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "orders_number_unique" ON "orders" ("number"); CREATE UNIQUE INDEX "orders_public_token_unique" ON "orders" ("public_access_token"); CREATE UNIQUE INDEX "orders_idempotency_key_unique" ON "orders" ("idempotency_key");
CREATE TABLE "order_items" ("id" text PRIMARY KEY NOT NULL, "order_id" text NOT NULL REFERENCES "orders"("id") ON DELETE cascade, "product_name" text NOT NULL, "variant_name" text, "quantity" integer NOT NULL, "unit_price_cents" integer NOT NULL, "subtotal_cents" integer NOT NULL, "options" jsonb NOT NULL); CREATE TABLE "order_status_history" ("id" text PRIMARY KEY NOT NULL, "order_id" text NOT NULL REFERENCES "orders"("id") ON DELETE cascade, "status" text NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
